fn to_uppercase(str1: &Vec<char>) -> Vec<char> {
    str1
        .iter()
        .map(|&c| {
            if c.is_ascii_lowercase() {
                // Convert 'a'..'z' to 'A'..'Z'
                c.to_ascii_uppercase()
            } else {
                // Leave everything else unchanged
                c
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::to_uppercase;

    #[test]
    fn empty_vector() {
        let input: Vec<char> = vec![];
        let output = to_uppercase(&input);
        assert!(output.is_empty());
    }

    #[test]
    fn all_lowercase() {
        let input: Vec<char> = "abcdefghijklmnopqrstuvwxyz".chars().collect();
        let output = to_uppercase(&input);
        assert_eq!(output, "ABCDEFGHIJKLMNOPQRSTUVWXYZ".chars().collect::<Vec<char>>());
    }

    #[test]
    fn mixed_characters() {
        let input: Vec<char> = "Hello, 世界! 123 abcXYZ".chars().collect();
        let output = to_uppercase(&input);
        // Only ASCII lowercase letters a–z become A–Z; everything else is unchanged
        assert_eq!(
            output,
            "HEllo, 世界! 123 ABCXYZ".chars().collect::<Vec<char>>()
        );
    }
}